out=[]
for row in inventory:
    r=manifest[row['docId']]
    f=facts[r['docId']].copy()
    base={k:r.get(k) for k in ('docId','docNo','date','title','completedDate')}
    base.update(dict(cohortYear=2025,workYear=2025,costYear=2025,vat='별도',rawVat='별도',costStatus='완료보고 공사금액',budgetM=None,quoteM=None,recoveryM=None,caveats=[],sourceUrl=r['sourceUrl'],relatedDocIds=[x['onclick'].split("'")[1] for x in r.get('relatedLinks',[])],sourceIds=[r['docId']]))
    base.update(f)
    base['rawCostM']=base['costM']
    base['countedCostM']=base['costM']
    base['includeInCostTotal']=base['costM'] is not None
    base['expenseGroupId']='2025-'+r['docId'] if base['costM'] is not None else None
    if base['costM'] is None:
        base['costYear']=None
    out.append(base)

assert len(out)==20 and len({r['docId'] for r in out})==20
assert sum(Decimal(str(r['costM'])) for r in out if r['costM'] is not None)==Decimal('351.13')
assert sum(r['costM'] is not None for r in out)==17
assert next(r for r in out if r['docId']=='329459')['saleContractM']==4
(W/'audit_2025_b.json').write_text(json.dumps(out,ensure_ascii=False,indent=2),encoding='utf8')
